function env(name) {
    try { return String($env[name] || '').trim(); } catch (error) { return ''; }
  }
  function readHeader(headers, name) {
    const target = name.toLowerCase();
    for (const [key, value] of Object.entries(headers || {})) {
      if (String(key).toLowerCase() === target) return Array.isArray(value) ? value[0] : value;
    }
    return '';
  }
  function safeEqual(left, right) {
    const a = String(left || '');
    const b = String(right || '');
    if (!a || a.length !== b.length) return false;
    let difference = 0;
    for (let index = 0; index < a.length; index += 1) difference |= a.charCodeAt(index) ^ b.charCodeAt(index);
    return difference === 0;
  }
  const input = $input.first().json || {};
  if (!input.headers || typeof input.headers !== 'object') {
    return [{ json: { health_trigger_allowed: true, health_trigger_source: 'schedule' } }];
  }
  const expected = env('RENOV_INTERNAL_TOKEN');
  const authorization = String(readHeader(input.headers, 'authorization') || '');
  const provided = readHeader(input.headers, 'x-internal-token')
    || (/^Bearer\s+/i.test(authorization) ? authorization.replace(/^Bearer\s+/i, '').trim() : '');
  return [{ json: {
    health_trigger_allowed: Boolean(expected && safeEqual(provided, expected)),
    health_trigger_source: 'webhook',
  } }];

function validAlertUrl(value) {
  const text = String(value || '').trim();
  const match = text.match(/^https:\/\/([a-z0-9.-]+)(?::([0-9]{1,5}))?(\/[^\s#]*)?$/i);
  if (!match) return '';
  if (match[2] && Number(match[2]) > 65535) return '';
  if (match[1].startsWith('.') || match[1].endsWith('.') || match[1].includes('..')) return '';
  return text;
}

function env(name) {
    try { return String($env[name] || '').trim(); } catch (error) { return ''; }
  }
  function parse(value, fallback) {
    if (value && typeof value === 'object') return value;
    try { return JSON.parse(String(value || '')); } catch (error) { return fallback; }
  }
  const row = $input.first().json || {};
  const categories = parse(row.categories, []);
  const metrics = parse(row.metrics, {});
  const alertUrl = validAlertUrl(env('RENOV_OBSERVABILITY_ALERT_URL'));
  const alertRequired = row.alert_required === true || row.alert_required === 'true';
  const alreadyNotified = row.already_notified === true || row.already_notified === 'true';
  const alertKey = typeof row.alert_key === 'string' ? row.alert_key : '';
  const payload = {
    project: 'renovaciones',
    environment: 'dev',
    severity: 'critical',
    kind: 'pilot_health',
    generated_at: row.generated_at || null,
    window_minutes: Number(row.window_minutes || 15),
    categories: Array.isArray(categories) ? categories.slice(0, 8) : [],
    metrics,
  };
  return [{ json: {
    alert_required: alertRequired,
    alert_already_notified: alreadyNotified,
    alert_configured: Boolean(alertUrl),
    alert_config_missing: alertRequired && !alreadyNotified && !alertUrl,
    alert_should_send: alertRequired && !alreadyNotified && Boolean(alertUrl) && Boolean(alertKey),
    alert_url: alertUrl || null,
    alert_key: alertKey || null,
    alert_kind: 'pilot_health',
    alert_payload: payload,
  } }];

function clean(value, fallback = '') {
    const text = String(value || fallback).replace(/[\u0000-\u001f\u007f]/g, ' ').trim();
    return text.slice(0, 120);
  }
  const input = $input.first().json || {};
  const workflow = input.workflow && typeof input.workflow === 'object' ? input.workflow : {};
  const execution = input.execution && typeof input.execution === 'object' ? input.execution : {};
  const workflowId = clean(workflow.id, 'unknown-workflow');
  const workflowName = clean(workflow.name, 'Unknown workflow');
  const executionId = clean(execution.id, `unknown-${Date.now()}`);
  const lastNode = clean(execution.lastNodeExecuted, 'unknown');
  const alertKey = `workflow-error:${workflowId}:${executionId}`;
  const payload = {
    project: 'renovaciones',
    environment: 'dev',
    severity: 'critical',
    kind: 'workflow_error',
    occurred_at: new Date().toISOString(),
    workflow: { id: workflowId, name: workflowName },
    execution_id: executionId,
    last_node: lastNode,
  };
  return [{ json: {
    alert_key: alertKey,
    alert_kind: 'workflow_error',
    alert_payload: payload,
    error_record_sql: "WITH input AS (\n  SELECT\n    $1::text AS event_type,\n    $2::text AS correlation_id,\n    $3::jsonb AS payload,\n    $4::boolean AS success,\n    NULLIF(left($5::text, 500), '') AS error_message,\n    COALESCE($6::boolean, false) AS deduplicate\n), inserted AS (\n  INSERT INTO renovation_dev.interaction_logs (\n    event_type,\n    correlation_id,\n    payload,\n    success,\n    error_message\n  )\n  SELECT\n    event_type,\n    correlation_id,\n    payload,\n    success,\n    CASE WHEN success THEN NULL ELSE COALESCE(error_message, 'OBSERVABILITY_ALERT_FAILED') END\n  FROM input\n  WHERE NOT deduplicate\n     OR NOT EXISTS (\n       SELECT 1\n       FROM renovation_dev.interaction_logs existing\n       WHERE existing.event_type = input.event_type\n         AND existing.correlation_id = input.correlation_id\n     )\n  RETURNING id\n)\nSELECT EXISTS (SELECT 1 FROM inserted) AS recorded",
    error_record_params: [
      'workflow_error_detected',
      alertKey,
      JSON.stringify(payload),
      false,
      'WORKFLOW_EXECUTION_ERROR',
      true,
    ],
  } }];

