function env(name) {
    try { return String($env[name] || '').trim(); } catch (error) { return ''; }
  }
  const original = $('Code - Shape Workflow Error').item.json || {};
  const recorded = $input.first().json?.recorded === true || $input.first().json?.recorded === 'true';
  const alertUrl = validAlertUrl(env('RENOV_OBSERVABILITY_ALERT_URL'));
  return [{ json: {
    alert_required: recorded,
    alert_already_notified: !recorded,
    alert_configured: Boolean(alertUrl),
    alert_config_missing: recorded && !alertUrl,
    alert_should_send: recorded && Boolean(alertUrl),
    alert_url: alertUrl || null,
    alert_key: original.alert_key || null,
    alert_kind: 'workflow_error',
    alert_payload: original.alert_payload || {},
  } }];
